  &quot;role&quot;: &quot;assistant&quot;,
  &quot;content&quot;: &quot;&quot;,
  &quot;tool_calls&quot;: [
    {
      &quot;id&quot;: &quot;call_1&quot;,
      &quot;type&quot;: &quot;function&quot;,
      &quot;function&quot;: {
        &quot;name&quot;: &quot;weather&quot;,
        &quot;arguments&quot;: &quot;{ \&quot;city\&quot;: \&quot;上海\&quot;, \&quot;date\&quot;: \&quot;today\&quot; }&quot;
      }
    }
  ]
}类似这种json 我会根据返回的结果执行 然后再把得到的结果 和之前的历史一起发过去
